const identifyTaskDB=[{"s":"La salida masiva de la pobreza y de la muerte temprana en dos siglos.","type":"La gran fuga (Deaton, 2013)"},{"s":"Mercados, propiedad privada, trabajo asalariado y ganancia reinvertida.","type":"La definición corta de Kocka (2016)"},{"s":"Un factor de alrededor de treinta en el nivel de vida del habitante común.","type":"El gran enriquecimiento (McCloskey, 2010)"},{"s":"Que la causa fue la dignidad concedida al comerciante y al inventor.","type":"Tesis causal de McCloskey: se cita como tesis"},{"s":"Discutir si el umbral es demasiado bajo para llamarle vida.","type":"La pelea de la línea (Hickel contra Roser, 2019)"},{"s":"Discutir a qué arreglo se le apunta el tramo mayor desde 1980.","type":"La pelea de la atribución"},{"s":"El de Mánchester no era el de Bismarck, ni el nórdico es el anglosajón.","type":"Las variedades del sistema"},{"s":"Cooperación entre extraños que no se conocen ni se deben nada.","type":"La mejor defensa moral: el intercambio voluntario"},{"s":"Qué afirma, cuánto, según quién, con qué línea y quién lo disputa.","type":"La hoja de la cifra"},{"s":"Un número grande dicho sin fecha, sin línea y sin contradictor.","type":"La cifra suelta: el modo de fallar de la etapa"}];
const classifyTaskDB=[{"w":"Deaton (2013)","gen":"Fuente","n":"La gran fuga: salud y riqueza","g":"«El gran escape», Nobel en 2015","t":"Clásico sólido reciente"},{"w":"McCloskey (2010)","gen":"Fuente","n":"El gran enriquecimiento, factor de treinta","g":"«Bourgeois Dignity»","t":"Sólida en los datos, y su causa entra como tesis"},{"w":"Kocka (2016)","gen":"Fuente","n":"La definición corta y las variedades","g":"«Historia del capitalismo»","t":"Síntesis académica breve"},{"w":"Banco Mundial y Our World in Data","gen":"Serie","n":"Las cifras de pobreza en el tiempo","g":"Se citan siempre con fecha y con su línea","t":"Serie estadística, con fecha"},{"w":"Hickel contra Roser (2019)","gen":"Disputa","n":"Si la línea de pobreza es demasiado baja","g":"Con Pinker de por medio","t":"Disputa viva de medición"},{"w":"El tramo chino desde 1980","gen":"Disputa","n":"A qué arreglo se le apunta la salida","g":"Un híbrido de partido y Estado con mercado","t":"Dato establecido, atribución en disputa"},{"w":"Bismarck (1883)","gen":"Hecho","n":"El seguro obligatorio de enfermedad","g":"Prueba de que las variedades son viejas","t":"Hecho histórico fechado"},{"w":"El intercambio voluntario","gen":"Concepto","n":"Cooperación entre extraños","g":"La mejor defensa moral, dicha entera","t":"El acero de la etapa"},{"w":"La hoja de la cifra","gen":"Herramienta","n":"Cinco renglones para todo número grande","g":"Con los cinco es prueba; sin uno, adorno","t":"El producto de la etapa"},{"w":"La cifra suelta","gen":"Error","n":"El número sin sus cuatro datos","g":"Sin fecha, sin línea, sin contradictor","t":"El modo de fallar de esta etapa"}];
