function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un banco ofrece patrocinar M.E.T.A.S con L 300,000 anuales: su logo en la portada de cada misión y una misión de educación financiera donde los ejemplos sean sus productos."},{"txt":"La familia estudia cobrar M.E.T.A.S a los colegios privados, unos L 50 por alumno al año, manteniéndolo gratis para las escuelas públicas."},{"txt":"La fundación de una empresa extractiva ofrece L 150,000 en tabletas para escuelas cercanas a su operación, con entrega pública y fotos."},{"txt":"Para su exposición del jueves, Jael escribió en la lámina: «la pobreza en el mundo bajó de un tercio a una décima parte». El dato es verdadero."},{"txt":"Llegan dos materiales escolares: uno afirma que el libre mercado sacó al mundo de la pobreza, y el otro que el capitalismo produjo la pobreza del mundo."},{"txt":"Después de oír las cifras, Angelly hace la pregunta directa: si entonces el capitalismo es bueno o es malo."},{"txt":"Aparece el dato que los dos bandos usan y ninguno cuenta entero: el tramo mayor de la salida de la pobreza desde 1980 ocurrió en China, bajo un híbrido."},{"txt":"La casa juzga su propio proyecto y tiene que decidir contra qué lo compara: contra la escuela ideal que se imagina, o contra las alternativas reales."}];
const critCaseQuestions=["1. Haz primero el acero: enuncia el mejor caso de lo que hay sobre la mesa, con sus números si los tiene, y dicho sin mueca.","2. Llena la hoja de la cifra o de la oferta: qué afirma exactamente, cuánto, según quién y de qué año, con qué línea o método, y quién lo disputa.","3. Si hay disputa, di de cuál de las dos se trata (la de la línea o la de la atribución) y qué fuente la sostiene, con su etiqueta de estatus.","4. ¿Qué se decide, con qué condición escrita, y qué queda en pie pase lo que pase con las disputas? Añade el renglón de qué evidencia haría cambiar la decisión."];
const critCaseGuides=["Se empieza por el acero, y no es una cortesía: es la licencia para lo que viene después. El mejor caso se enuncia entero, con sus números más fuertes y con la voz de quien de verdad lo defendería, sin mueca y sin el «sí, pero» adelantado. Si lo que hay sobre la mesa es una oferta con lempiras, el acero es decir qué mete de verdad: cuánto dinero, para qué alcanza, qué se podría hacer con eso que hoy no se hace. Si lo que hay es una cifra, el acero es enunciarla en su versión más fuerte y más citable. La prueba de que el acero está bien hecho es incómoda y es la de esta casa: que quien defiende esa postura lo firmaría sin corregir una coma. Quien no puede hacer eso no está autorizado a auditar nada, y en este expediente esa regla no admite excepción, porque es la misma que rige en el gemelo rojo.","La hoja tiene cinco renglones y ninguno es decorativo. Qué afirma exactamente, en una oración con sujeto, verbo y número, y sin adjetivos, porque el adjetivo es por donde se cuela la conclusión. Cuánto, con su horquilla si la tiene, y con el hueco declarado si no se consigue. Según quién, con obra, autor, año y la etiqueta de estatus que le toca: Deaton (2013) como clásico sólido reciente, McCloskey (2010) con su etiqueta doble, Kocka (2016) como síntesis académica breve, las series del Banco Mundial y de Our World in Data siempre con fecha. Con qué método y con qué línea, porque una cifra de pobreza sin el umbral con que se midió no dice nada. Y quién lo disputa, junto con qué dato resolvería el pleito. Cuando lo que hay sobre la mesa es una oferta y no una cifra, los mismos cinco renglones se leen así: qué se ofrece, cuánto en lempiras, quién lo ofrece y de qué vive, con qué condiciones escritas, y quién saldría perdiendo si se acepta.","Si hay disputa, lo primero es decir de cuál se trata, porque en esta materia son dos y se confunden todo el tiempo. La pelea de la línea discute cuánto cayó la pobreza y si el umbral con que se mide no será demasiado bajo: ahí están Jason Hickel de un lado y Max Roser y Steven Pinker del otro, en el cruce de 2019, y es una disputa viva de medición que se enseña como disputa y no como bando. La pelea de la atribución discute a qué arreglo se le apunta el resultado, y su dato central es que el tramo mayor de la salida desde 1980 ocurrió en China bajo un híbrido de partido y Estado con mercado; ese dato incomoda a los dos lados y por eso se cuenta entero. El puente entre las dos son las variedades de Kocka: si el sistema vino en variedades desde el arranque, preguntar por «el capitalismo» a secas es la pregunta mal hecha. Y se dice también lo que aquí no se contesta: las fallas de mercado son la etapa 2, los bienes que el precio corrompe la 3, y la desigualdad, el clima y los expedientes históricos la 4.","Todo caso cierra con dos casillas que son las que separan el oficio del desahogo. La primera es la decisión con su condición escrita: aceptar con condiciones es el resultado normal de una auditoría y no una derrota, y la condición se escribe antes y no después, con quién firma y qué pasa si se incumple. La segunda es qué queda en pie pase lo que pase con las disputas, dicho en voz alta: por ejemplo, que nadie discute que la gente vive mucho más y muere mucho menos de niña que hace dos siglos, y que ninguna de las dos peleas toca ese registro. Encima de las dos va el pago, que es la regla de esta casa: la comparación se hace contra las alternativas reales y no contra el paraíso, también cuando el objeto auditado es el proyecto propio; y la decisión lleva su renglón de qué evidencia la haría cambiar, con fecha, porque sin ese renglón una premisa está funcionando como dogma."];

const critErrorBank=[{"txt":"\"La pobreza en el mundo bajó de un tercio a una décima parte\".","g1":"El dato es verdadero y aun así la frase no sirve: no dice de qué años habla, con qué línea se midió, quién publicó la serie ni quién la discute. Así escrita es un número prestado a favor de una postura.","g2":"La corrección cabe en la misma lámina: «según las series del Banco Mundial y de Our World in Data, la pobreza extrema pasó de más de un tercio de la humanidad hacia 1990 a alrededor de una décima parte antes de la pandemia; Hickel discute que esa línea sea demasiado baja y Roser le responde, y la disputa sigue viva desde 2019»."},{"txt":"\"McCloskey demostró que la causa fue la dignidad concedida al comerciante\".","g1":"Se pegaron un dato y una tesis con la misma cola. El cálculo del gran enriquecimiento, un factor de alrededor de treinta, es sólido; la explicación causal que ella propone es suya y está discutida por otros historiadores.","g2":"La corrección es de dos verbos: McCloskey calcula un factor de alrededor de treinta, y sostiene que la causa fue la dignidad burguesa. Calcula y sostiene no son la misma operación, y no se citan igual aunque vengan en el mismo libro."},{"txt":"\"El capitalismo sacó al mundo de la pobreza\".","g1":"Falta la advertencia de Kocka: el sistema vino en variedades desde el arranque, y la palabra en singular cubre cosas que no se parecen. Y falta el dato que lo complica: el tramo mayor desde 1980 fue en China, bajo un híbrido.","g2":"La corrección obliga a especificar: qué variedad, en qué países, en qué años, y qué se hace con el tramo chino. Una vez especificado, la frase se puede discutir; sin especificar, gana siempre y por eso no afirma nada."},{"txt":"\"Como la línea de pobreza está discutida, esas cifras no valen nada\".","g1":"Es el error simétrico y también es cifra suelta: de que un umbral esté en disputa no se sigue que todo el registro se caiga. La mortalidad infantil y la esperanza de vida no dependen de esa línea y cuentan la misma historia.","g2":"La corrección es separar lo que la disputa toca de lo que no toca: la pelea de la línea afecta a cuánto se llama salida de la pobreza, y no afecta a las actas de defunción. Eso queda en pie, y decirlo es parte del trabajo."},{"txt":"\"Este expediente celebra la fuga; las facturas ya las veremos\".","g1":"Se leyó medio título. Deaton escribió salud, riqueza y los orígenes de la desigualdad, y esa segunda mitad es el argumento: de toda fuga se queda gente adentro. Aplazar no es esconder, pero hay que decir dónde está lo aplazado.","g2":"La corrección es declarar el calendario: las fallas de la máquina en la etapa 2, lo que el dinero no debe comprar en la 3, la desigualdad y el clima en la 4, y el archivo junto al expediente rojo, que la Bóveda no acepta uno sin el otro."},{"txt":"\"Ese dato me sirve, lo pongo en la lámina\".","g1":"Se saltó la regla del placer, que es la más incómoda de la materia: el dato que confirma lo que uno ya creía paga doble auditoría, precisamente porque es el que menos ganas dan de verificar.","g2":"La corrección son tres pasos: buscar el dato en su fuente original, buscar activamente quién lo discute, y anotarlo con la misma letra aunque estropee la lámina que ya estaba hecha."}];

const critDecisionBank=["El banco espera respuesta por los L 300,000: ¿se acepta, se acepta con condiciones o no se acepta? ¿Qué dice el contrato exactamente sobre los ejemplos de la misión?","La familia tiene que decidir el cobro de L 50 por alumno a los colegios privados: ¿se cobra, y qué se escribe antes para que no toque nunca a la escuela pública?","La fundación extractiva espera por las L 150,000 en tabletas: ¿se aceptan, y qué se firma antes de que lleguen?","La lámina de Jael se imprime mañana: ¿qué frase exacta va, con qué fuente y con qué nombre del que la discute?","Los dos materiales escolares están sobre la mesa: ¿cuál se usa, cuál se guarda como ejercicio, y qué etiqueta se le escribe encima al que se guarda?","Angelly espera la respuesta a si el capitalismo es bueno o malo: ¿qué se le contesta a su edad, y cómo se le explica por qué la pregunta se cambia?","El dato de China va a entrar en el expediente: ¿en cuál de las dos peleas se coloca, y con qué nota al margen para que no lo use ningún bando a medias?","La casa va a evaluar M.E.T.A.S: ¿contra qué alternativa real se compara, y qué evidencia haría que la casa dijera que hay algo mejor y se corriera a un lado?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden, y el orden es el método. Primero el acero: se enuncia el mejor caso de lo que hay sobre la mesa con sus números más fuertes y con la voz de quien de verdad lo defendería, sin mueca y sin el pero adelantado; la prueba de que está bien hecho es que quien sostiene esa postura lo firmaria sin corregir una coma, y quien no puede hacer eso no esta autorizado a auditar nada. Después se llena la hoja de la cifra, que tiene cinco renglones y ninguno es decorativo: que afirma exactamente, en una oración con sujeto y número y sin adjetivos; cuánto, con su horquilla si la tiene y con el hueco declarado si no; según quién, con obra, autor, año y etiqueta de estatus, que aquí son Deaton 2013 como clásico sólido reciente, McCloskey 2010 sólida en los datos y con su explicación causal entrando como tesis, Kocka 2016 como síntesis académica breve, y las series del Banco Mundial y de Our World in Data siempre con fecha; con qué método y con qué línea o umbral, porque una cifra de pobreza sin el umbral no dice nada; y quién lo disputa, junto con qué dato resolvería el pleito. Si hay disputa se dice de cuál de las dos se trata, porque son dos y se confunden todo el tiempo: la de la línea discute cuánto cayó, con Hickel de un lado y Roser y Pinker del otro en el cruce de 2019, y la de la atribución discute a qué arreglo se le apunta, con el tramo chino desde 1980 como dato central; el puente entre las dos son las variedades de Kocka. Y al final van las dos casillas que separan el oficio del desahogo: la decisión con su condición escrita, porque aceptar con condiciones es el resultado normal de una auditoría y no una derrota, y qué queda en pie pase lo que pase con las disputas. Encima de las dos va la regla de la casa: no se compara con el paraíso sino con las alternativas reales, también cuando el objeto auditado es el proyecto propio, y toda decisión lleva su renglon de que evidencia la haria cambiar, con fecha.";

const critCompareBank=[{"a":"Escribir «según el Banco Mundial, la pobreza extrema pasó de más de un tercio hacia 1990 a una décima parte antes de la pandemia, y Hickel discute esa línea».","b":"Escribir «la pobreza en el mundo bajó muchísimo».","ga":"Caso A: es el mismo dato con sus cuatro apoyos, así que se puede discutir, corregir y sostener de pie delante de alguien que piense distinto.","gb":"Caso B: cabe mejor en una diapositiva y no afirma nada verificable; sirve para ganar en el aula y se desarma con una sola pregunta.","gr":"La diferencia no es de rigor académico sino de uso: solo la primera se puede usar para decidir algo, y decidir es para lo que la casa estudia."},{"a":"Hacer el acero del sistema antes de abrir las disputas.","b":"Abrir las disputas primero, porque el acero suena a propaganda.","ga":"Caso A: da la licencia para auditar, obliga a leer las fuentes del otro lado y hace que la crítica posterior tenga peso ante cualquiera.","gb":"Caso B: se siente más honesto y produce lo contrario, porque una crítica de algo que no se supo defender se lee como identidad, y con razón.","gr":"La regla del acero se enseña en el expediente rojo y aquí se aplica igual: esta casa no tiene una vara para cada bando."},{"a":"Separar la pelea de la línea de la pelea de la atribución.","b":"Discutir cuánto cayó y a qué se debió en la misma frase.","ga":"Caso A: cada pelea recibe la clase de prueba que le corresponde, la metodológica una y la histórica comparada la otra, y las dos pueden avanzar.","gb":"Caso B: es lo que hace casi todo el mundo, y por eso esas conversaciones no terminan nunca ni cambian de opinión a nadie.","gr":"Mezclar las dos peleas es como discutir a la vez cuánto pesa algo y de quién es: las dos preguntas son buenas y ninguna se contesta así."},{"a":"Comparar el proyecto propio con las alternativas reales.","b":"Comparar el proyecto propio con la escuela ideal que uno se imagina.","ga":"Caso A: es la abstracción central de la materia aplicada en casa, y da un veredicto que se puede usar, además de aceptarse en las dos direcciones.","gb":"Caso B: da siempre el resultado que uno tenga ganas ese día, brillante o miserable, y por eso no informa ninguna decisión.","gr":"No se compara con el paraíso: se compara con las alternativas reales, y esa regla vale igual para el sistema que para el proyecto de la casa."}];

const critCauseBank=[{"cause":"Se cita un número grande sin fecha, sin línea y sin contradictor.","guide":"La cifra queda como adorno: puede ser verdadera y no prueba nada, se desarma con una sola pregunta, y de paso enseña a los que escuchan que en esta casa los números se usan como banderas."},{"cause":"Se hace el acero del sistema antes de abrir las disputas.","guide":"La auditoría que viene después gana peso ante cualquiera, incluido el que defiende lo auditado, y quien estudia aprende que la licencia para criticar se saca leyendo al otro lado."},{"cause":"Se mezclan la pelea de la línea y la pelea de la atribución.","guide":"Ninguna de las dos avanza, porque cada una necesita una clase de prueba distinta, y la conversación se convierte en un intercambio de banderas donde el que grita más parece tener razón."},{"cause":"Se dice «el capitalismo» en singular y se le apunta la fuga entera.","guide":"Se pierde de vista que el sistema vino en variedades, y con ello la única pregunta que rinde: qué mercados, con qué reglas y para qué bienes, que es la que se contesta uno por uno y decide cosas."},{"cause":"Se celebra la fuga sin mirar a los que quedaron adentro.","guide":"Se lee medio título de Deaton y se convierte una investigación seria en propaganda; además se pierde el hilo que conecta esta etapa con las tres siguientes, que es exactamente ese hueco."},{"cause":"La casa aplica la regla del placer a sus propios datos cómodos.","guide":"Aparecen las cifras que se estaban repitiendo sin verificar, se corrigen con fuente y fecha, y el expediente empieza a poder sostenerse delante de alguien que piensa distinto, que es la única prueba que vale."}];
const critEffectBank=[{"effect":"Los L 300,000 del banco se aceptaron con el logo en créditos y cero productos propios en los ejemplos.","guide":"La pregunta que decidió fue si la misión enseñaría lo mismo con otro patrocinador. Con logo fuera del contenido, cláusula de salida sin penalidad y el trato publicado donde cualquier maestro lo pueda leer, la respuesta es sí, y por eso se aceptó con condiciones."},{"effect":"El cobro a colegios privados quedó aprobado, y la escuela pública quedó blindada por escrito.","guide":"El precio no alcanza a la escuela pública ni condiciona qué misiones se escriben, las cuentas se publican a la vista, y la opción de abrir el código y sostenerlo en comunidad quedó evaluada por escrito antes de decidir. Lo que el precio le hace al bien es la etapa 3, y se nombró sin contestarla."},{"effect":"Las tabletas se aceptaron con independencia editorial firmada antes de la entrega.","guide":"La donación quedó publicada con monto y fecha, y con el compromiso de que si algún día hay ficha sobre ese río se escribe con la misma doble columna que todo lo demás. El caso entró como categoría y no con nombre propio, que es la regla de selección de esta materia."},{"effect":"La lámina de Jael se reescribió y quedó más larga y más útil.","guide":"El mismo dato con sus cuatro apoyos: la fuente, los años, la línea y el nombre de quien la discute. Sigue cabiendo en la lámina, y ahora se puede defender delante de un maestro que pregunte de dónde salió."},{"effect":"De los dos materiales escolares no se usó ninguno como fuente.","guide":"Los dos fallaban en el mismo sitio: ni años, ni línea, ni países, ni contradictor. Se guardaron como ejercicio, con la etiqueta escrita encima para que nadie los cite después por error, y se usaron en clase precisamente para mostrar que la vara es una sola para los dos estantes."},{"effect":"El dato de China quedó en el expediente, en la pelea de la atribución y con su nota al margen.","guide":"La nota dice que corta en las dos direcciones: obliga al que celebra a explicar el híbrido y al que acusa a explicar qué cambió al final de los setenta. Y queda apuntada la disciplina de la casa: cuando un dato incomoda a los dos bandos, casi siempre es el dato bueno."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`📒 La cifra sobre la mesa · Forma ${cf} · La gran fuga · Ruta del Expediente Dorado`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La cifra sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Cuál es el mejor caso de lo que hay sobre la mesa, dicho con sus números y sin mueca? Llena después la hoja de la cifra, di de cuál de las dos disputas se trata si la hay, con qué fuente y con qué etiqueta, y qué queda en pie pase lo que pase.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se puede sostener de pie y cuál se desarma con una pregunta? 2. ¿Por qué no son la misma decisión?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La cifra sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La cifra sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Cuál es el mejor caso de lo que hay sobre la mesa, dicho con sus números y sin mueca? Llena después la hoja de la cifra, di de cuál de las dos disputas se trata si la hay, con qué fuente y con qué etiqueta, y qué queda en pie pase lo que pase.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se puede sostener de pie y cuál se desarma con una pregunta? 2. ¿Por qué no son la misma decisión?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La cifra sobre la mesa La gran fuga · Ruta del Expediente Dorado · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #854d0e;background:#fffbeb;color:#854d0e;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#854d0e;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #854d0e;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#fffbeb;border-left:3px solid #854d0e;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#fffbeb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#fffbeb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#854d0e;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #854d0e;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La cifra sobre la mesa · La gran fuga · Ruta del Expediente Dorado · Etapa 1 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La cifra sobre la mesa · La gran fuga · Ruta del Expediente Dorado · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

