const timelineData=[{"y":"1883","icon":"🧵","label":"Bismarck, y las variedades","text":"Mientras en Inglaterra se discutía si el Estado debía existir, <strong>Bismarck monta el seguro obligatorio de enfermedad</strong> para los trabajadores. Es la prueba fechada de que <strong>el sistema vino en variedades desde el arranque</strong>: el de Mánchester no era el de Bismarck, y la palabra en singular ya es una simplificación."},{"y":"1963","icon":"🎬","label":"La película del título","text":"Se estrena una película sobre una <strong>evasión</strong>, y medio siglo después un economista le tomará prestado el nombre para su libro. El detalle no es anecdótico: la metáfora de la fuga trae consigo <strong>la idea de que algunos salen y otros no</strong>, que es la mitad del argumento."},{"y":"1990","icon":"📉","label":"El punto de partida de la serie","text":"Es el año desde el que se suele contar la caída: hacia entonces estaba en pobreza extrema <strong>más de un tercio de la humanidad</strong>, según las series del <strong>Banco Mundial</strong> y de <strong>Our World in Data</strong>. La cifra <strong>nunca se cita sin el año y sin la línea</strong> con que se midió."},{"y":"2010","icon":"📈","label":"McCloskey y el gran enriquecimiento","text":"En <strong>«Bourgeois Dignity»</strong>, Deirdre McCloskey calcula un factor de alrededor de <strong>treinta</strong> en el nivel de vida del habitante común. Etiqueta doble y las dos juntas: <strong>sólida en los datos</strong>, y su explicación causal (la dignidad del comerciante y del inventor) <strong>entra como tesis y no como consenso</strong>."},{"y":"2013","icon":"🏃","label":"Deaton y la gran fuga","text":"Se publica <strong>«El gran escape: salud, riqueza y los orígenes de la desigualdad»</strong>. Etiqueta: <strong>clásico sólido reciente</strong>. Y la segunda mitad del título es el argumento y no un apéndice: <strong>de toda fuga se queda gente adentro</strong>."},{"y":"2015","icon":"🏅","label":"El Nobel","text":"Angus Deaton recibe el <strong>Nobel de Economía</strong>. Importa para el estatus de la fuente: no es un ensayista de aeropuerto ni un panfletario, es el consenso profesional reconociendo un trabajo. Lo cual <strong>no lo vuelve inmune a la auditoría</strong>, solo obliga a hacerla en serio."},{"y":"2019","icon":"⚔️","label":"Hickel contra Roser","text":"<strong>Jason Hickel</strong> sostiene que la línea de pobreza es demasiado baja para llamarle vida a lo que hay encima; <strong>Max Roser</strong> responde con las series largas, y <strong>Steven Pinker</strong> defiende la lectura optimista. Etiqueta: <strong>disputa viva de medición</strong>, y <strong>viva se enseña</strong>: quien diga que está resuelta está vendiendo bando."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

