let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(prueba){sfx(prueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(prueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🧾</span><span class="ms-text"><strong>La cifra entró con sus cinco renglones:</strong> «según las series del Banco Mundial y de Our World in Data, la pobreza extrema pasó de más de un tercio de la humanidad hacia 1990 a alrededor de una décima parte antes de la pandemia». Mismo dato, ahora con año y con fuente.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">⚔️</span><span class="ms-text"><strong>Y el renglón que casi nadie llena:</strong> «Jason Hickel discute que esa línea sea demasiado baja, y Max Roser le responde con las series largas; el cruce es de 2019 y sigue abierto». Con eso la lámina se puede defender delante de cualquiera.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🎈</span><span class="ms-text"><strong>Quedó una cifra suelta:</strong> un número verdadero sin año, sin línea, sin fuente y sin contradictor. Suena redondo, cabe en la diapositiva y nadie va a discutirlo en el aula, que es justo el problema.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> la primera persona que pregunte con qué línea se midió desarma la lámina entera, y de camino queda enseñado que en esta casa los números se usan como banderas. Se tacha y se reescribe con los cinco renglones.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

