const parteData={"definicion":{"nombre":"La definición de Kocka","icon":"📖","estructura":{"title":"Qué es","info":"• De <strong>«Historia del capitalismo»</strong>, síntesis académica breve<br>• Cuatro piezas: <strong>mercados, propiedad privada, trabajo asalariado y ganancia reinvertida</strong><br>• Hacen falta <strong>las cuatro juntas</strong>: con tres no alcanza"},"funcion":{"title":"Cómo se reconoce","info":"• Los precios se forman en el intercambio y no los fija una autoridad<br>• La mayoría vive de <strong>vender su tiempo</strong> por un salario<br>• Y la ganancia <strong>vuelve al negocio</strong> en vez de gastarse entera"},"enfermedades":{"title":"Dónde se cae","info":"• Discutir el sistema <strong>sin definirlo</strong>, que es lo que hace casi todo el mundo<br>• Usar la palabra <strong>en singular</strong> como si nombrara una sola cosa<br>• Confundir <strong>mercado</strong> con <strong>capitalismo</strong>: hay mercados desde hace milenios"},"cuidados":{"title":"En esta casa","info":"• Definir viene <strong>antes</strong> que juzgar, y se dice el primer día<br>• La teoría de precios y los clásicos enteros <strong>viven en Economía política</strong><br>• Aquí se remiten y no se repiten: esta materia audita el sistema entero"}},"fuga":{"nombre":"La gran fuga","icon":"🏃","estructura":{"title":"Qué es","info":"• De <strong>Deaton (2013)</strong>, <strong>clásico sólido reciente</strong>, Nobel en 2015<br>• La salida masiva de <strong>la pobreza y de la muerte temprana</strong> en dos siglos<br>• Con <strong>McCloskey (2010)</strong>: el gran enriquecimiento, factor de treinta"},"funcion":{"title":"Cómo se reconoce","info":"• Pobreza extrema: <strong>más de un tercio hacia 1990, una décima antes de la pandemia</strong><br>• Mortalidad de menores de cinco: <strong>cerca de la mitad en 1800, menos de 1 de 20 hoy</strong><br>• Esperanza de vida: de rondar los <strong>treinta</strong> a superar los <strong>setenta</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Citar las cifras <strong>sin año y sin línea</strong>: eso es la cifra suelta<br>• Pegar el dato de McCloskey con <strong>su tesis causal</strong>, que es otra cosa<br>• Leer <strong>medio título</strong> de Deaton y olvidar los orígenes de la desigualdad"},"cuidados":{"title":"En esta casa","info":"• El acero primero: <strong>no se audita lo que no se sabe defender</strong><br>• Las facturas tienen etapa: <strong>la 2, la 3 y la 4</strong>, y no se adelantan<br>• Y este expediente <strong>se archiva junto al rojo</strong>: la Bóveda pide los dos"}},"disputas":{"nombre":"Las dos disputas","icon":"⚔️","estructura":{"title":"Qué es","info":"• <strong>La de la línea:</strong> cuánto cayó, y si el umbral no es muy bajo<br>• <strong>La de la atribución:</strong> a qué arreglo se le apunta el resultado<br>• Son <strong>dos</strong>, con distintos contendientes y distinta clase de prueba"},"funcion":{"title":"Cómo se reconoce","info":"• Línea: <strong>Hickel</strong> contra <strong>Roser</strong> y <strong>Pinker</strong>, en el cruce de <strong>2019</strong><br>• Atribución: el tramo mayor desde <strong>1980</strong> fue en <strong>China</strong>, bajo un híbrido<br>• Y ese dato <strong>incomoda a los dos bandos</strong>, que es la señal de que es bueno"},"enfermedades":{"title":"Dónde se cae","info":"• <strong>Mezclarlas</strong> en la misma frase, y así no avanza ninguna<br>• Declarar resuelta la de la línea: <strong>quien lo hace está vendiendo bando</strong><br>• Usar el dato de China <strong>a medias</strong>, solo por el lado que conviene"},"cuidados":{"title":"En esta casa","info":"• Las disputas vivas <strong>se enseñan vivas</strong>, con fecha y con los dos nombres<br>• Y con <strong>la regla del placer</strong>: el dato cómodo paga doble auditoría<br>• El puente entre las dos son <strong>las variedades de Kocka</strong>"}},"variedades":{"nombre":"Las variedades","icon":"🧵","estructura":{"title":"Qué es","info":"• El sistema <strong>vino en variedades desde el arranque</strong>, no después<br>• <strong>Mánchester</strong> no era <strong>Bismarck</strong>, que en 1883 montó el seguro de enfermedad<br>• Y el <strong>nórdico</strong> de hoy no es el <strong>anglosajón</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Hay <strong>dos diales distintos</strong>: cuánto mercado y cuánta redistribución<br>• Confundirlos es el error más común del debate entero<br>• Y explica por qué <strong>«el capitalismo» a secas</strong> es la pregunta mal hecha"},"enfermedades":{"title":"Dónde se cae","info":"• Apuntarle la fuga entera a <strong>una sola variedad</strong><br>• O culpar a <strong>una sola variedad</strong> de todas las facturas<br>• Usar las variedades como <strong>salida diplomática</strong> en vez de como puente"},"cuidados":{"title":"En esta casa","info":"• La pregunta que rinde: <strong>qué mercados, con qué reglas y para qué bienes</strong><br>• Las variedades entran a fondo en la <strong>etapa 5</strong>, y aquí se nombran<br>• Y la política hondureña de hoy <strong>no entra ni de ejemplo</strong>"}}};
let labParte='definicion',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterías sobre los cinco textos: comprensión lectora (25), completar
// (10) y análisis complejo (10). Los bancos se escriben desde
